Here’s a simple and efficient C++ program (iterative, O(n) time, O(1) space) to compute the nth term of the sequence defined by:
T0 = 0, T1 = -1, T2 = -1, and Tn = Tn-1 + Tn-2 + Tn-3 for n ≥ 3.

This version uses arbitrary-precision integers to avoid overflow.

#include <iostream>
#include <boost/multiprecision/cpp_int.hpp>

using boost::multiprecision::cpp_int;

cpp_int trib(int n) {
    if (n == 0) return 0;
    if (n == 1 || n == 2) return -1;

    cpp_int a = 0;   // T0
    cpp_int b = -1;  // T1
    cpp_int c = -1;  // T2

    for (int i = 3; i <= n; ++i) {
        cpp_int d = a + b + c;  // T(i)
        a = b;
        b = c;
        c = d;
    }
    return c;
}

int main() {
    int n;
    std::cout << "Enter n (0-based): ";
    if (!(std::cin >> n) || n < 0) {
        std::cerr << "Please enter a non-negative integer.\n";
        return 1;
    }

    cpp_int result = trib(n);
    std::cout << "T(" << n << ") = " << result << "\n";
    return 0;
}

