Here’s a simple linear-time, constant-space approach: walk through the two arrays like the merge step of merge sort, but stop once you reach the median position(s). Track only the last two seen elements.

Python implementation (O(m+n) time, O(1) extra space):
def median_two_sorted(a, b):
    m, n = len(a), len(b)
    total = m + n
    if total == 0:
        raise ValueError("Both arrays are empty")

    # Middle indices in the merged order
    mid1 = (total - 1) // 2
    mid2 = total // 2

    i = j = -1  # merged index counter
    p1 = p2 = 0  # pointers into a and b
    prev_val = curr_val = None

    while p1 < m or p2 < n:
        # Take next smallest from a or b
        if p2 >= n or (p1 < m and a[p1] <= b[p2]):
            val = a[p1]
            p1 += 1
        else:
            val = b[p2]
            p2 += 1

        i += 1
        if i == mid1:
            prev_val = val
        if i == mid2:
            curr_val = val
            break

    if total % 2 == 1:
        return float(curr_val)
    else:
        return (prev_val + curr_val) / 2.0

C++ implementation:
#include <vector>
using namespace std;

double findMedianSortedArrays(const vector<int>& A, const vector<int>& B) {
    int m = A.size(), n = B.size();
    int total = m + n;
    if (total == 0) throw std::invalid_argument("Both arrays are empty");

    int mid1 = (total - 1) / 2;
    int mid2 = total / 2;

    int i = 0, j = 0;
    int k = -1; // merged index
    long long prevVal = 0, currVal = 0; // use wider type to avoid overflow

    while (i < m || j < n) {
        int val;
        if (j >= n || (i < m && A[i] <= B[j])) {
            val = A[i++];
        } else {
            val = B[j++];
        }

        ++k;
        if (k == mid1) prevVal = val;
        if (k == mid2) { currVal = val; break; }
    }

    if (total % 2 == 1) return static_cast<double>(currVal);
    return (prevVal + currVal) / 2.0;
}

Notes:
- Time complexity: O(m + n).
- Space complexity: O(1).
- Works when one array is empty.
- For even total length, it averages the two middle values; for odd, it returns the middle value.

