#include <bits/stdc++.h>
using namespace std;

vector<int> intersection_unique(const vector<int>& a, const vector<int>& b) {
    const vector<int>* pa = &a;
    const vector<int>* pb = &b;
    if (a.size() > b.size()) { pa = &b; pb = &a; }

    unordered_set<int> s(pa->begin(), pa->end());
    vector<int> res;
    res.reserve(s.size());

    for (int x : *pb) {
        auto it = s.find(x);
        if (it != s.end()) {
            res.push_back(x);
            s.erase(it); // ensure uniqueness
        }
    }
    return res;
}

