from collections import Counter

def intersection_multi(a, b):
    if len(a) > len(b):
        a, b = b, a
    cnt = Counter(a)
    res = []
    for x in b:
        c = cnt.get(x, 0)
        if c > 0:
            res.append(x)
            c -= 1
            if c == 0:
                del cnt[x]
            else:
                cnt[x] = c
    return res

