#include <bits/stdc++.h>
using namespace std;

vector<int> intersection_multi(const vector<int>& a, const vector<int>& b) {
    const vector<int>* pa = &a;
    const vector<int>* pb = &b;
    if (a.size() > b.size()) { pa = &b; pb = &a; }

    unordered_map<int, int> freq;
    freq.reserve(pa->size() * 2);
    for (int x : *pa) ++freq[x];

    vector<int> res;
    for (int x : *pb) {
        auto it = freq.find(x);
        if (it != freq.end()) {
            res.push_back(x);
            if (--(it->second) == 0) freq.erase(it);
        }
    }
    return res;
}

int main() {
